#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef  struct{
         char name[100];
} ElemType;

typedef    struct   LNode  {
	ElemType            data;
	struct  LNode      * next;
} LNode;

int main()
{

	LNode* s = (LNode *) malloc ( sizeof (LNode) );	

	strcpy(s->data.name, "default");    	
	printf ("The value is: ");
    printf(s->data.name);	

    ElemType data = s->data;

	free (s);
	printf ("\nThen the value is: ");
    printf(data.name);	
    return(0);
}

